using System;using System.Linq;using System.Collections.Generic;using System.Globalization;
namespace BeamScheduleFormatter {
class WindExposureAudit {
 public string Exposure="Unresolved",Roughness="?",Reason="",Mix="";public readonly List<string[]> Checks=new List<string[]>();
 public double Height,BFetch,DFetch,Transition,Available,NearestWater=double.NaN,LongestWater;
}
static partial class WindAssessment {
 internal static List<WindSample>[] UpwindSector(WindTerrain terrain,int direction){int previous=(direction+7)%8,next=(direction+1)%8;return new[]{terrain.Rays[previous*3+1],terrain.Rays[direction*3],terrain.Rays[direction*3+1],terrain.Rays[direction*3+2],terrain.Rays[next*3+1]};}
 internal static WindExposureAudit AssessExposure(WindTerrain terrain,int direction,double meanHeight){return AssessExposure(UpwindSector(terrain,direction),meanHeight,true);}
 internal static WindExposureAudit AssessExposure(IEnumerable<List<WindSample>> sector,double meanHeight,bool twoSectors=false){var result=new WindExposureAudit{Height=meanHeight};var rays=sector.ToList();Func<double,string> f=value=>WindTin.Finite(value)?value.ToString("0.###",CultureInfo.InvariantCulture):"unresolved";
 result.Checks.Add(new[]{"Mean roof height h",f(meanHeight)+" m","Exposure fetch uses h, not the velocity-pressure reference z."});result.Checks.Add(new[]{"Upwind investigation",twoSectors?"Two adjacent45° sectors (±45°)":"Single45° screening sector","The more severe candidate governs the selected wind direction."});
 if(!WindTin.Finite(meanHeight)||meanHeight<=0){result.Reason="Mean roof height is missing or invalid. Enter building geometry; no exposure category is assumed.";return result;}
 result.BFetch=BFetch(meanHeight);result.DFetch=DFetch(meanHeight);result.Transition=DTransition(meanHeight);double required=Math.Max(result.BFetch,result.DFetch+result.Transition);result.Available=rays.Count==0?0:rays.Min(ray=>ray.Count==0?0:ray.Last().D);
 result.Checks.Add(new[]{"B required fetch",f(result.BFetch)+" m",meanHeight<=9.1?"h ≤9.1m: 457.2m":"max(792.48m,20h)"});result.Checks.Add(new[]{"D smooth fetch",f(result.DFetch)+" m","max(1524m,20h)"});result.Checks.Add(new[]{"D inland transition",f(result.Transition)+" m","max(182.88m,20h)"});result.Checks.Add(new[]{"Sample extent",f(result.Available)+" m",">= "+f(required)+"m required on every investigation ray"});
 var points=rays.SelectMany(ray=>ray.Where(p=>p.D>0&&p.D<=required)).ToList();if(points.Count>0){var groups=points.GroupBy(p=>Roughness(p.Cover)).OrderByDescending(g=>g.Count()).ToList();result.Roughness=groups[0].Key;result.Mix=string.Join("; ",groups.Select(g=>g.Key+" "+(100.0*g.Count()/points.Count).ToString("0.#",CultureInfo.InvariantCulture)+"%"));}result.Checks.Add(new[]{"Mapped sample mix",result.Mix,"Fractions of sampled points, not surveyed sector areas. B trees/built-up; C open classes; D water."});
 bool complete=(rays.Count==3||rays.Count==5)&&rays.All(ray=>ray.Count>0&&ray.First().D<=.01&&ray.Last().D>=required&&ray.TakeWhile(p=>p.D<required).All(p=>Roughness(p.Cover)!="?"));
 if(!complete||rays.Any(ray=>ray.FirstOrDefault(p=>p.D>=required)==null||Roughness(ray.First(p=>p.D>=required).Cover)=="?")){result.Reason="Insufficient ray extent or unsupported/no-data land cover within the required fetch. Exposure is unresolved; missing data is not converted to C.";return result;}
 int smoothRays=0;double shortestB=double.PositiveInfinity;foreach(var ray in rays){double bRun=0;foreach(var sample in ray){if(Roughness(sample.Cover)!="B")break;bRun=sample.D;}shortestB=Math.Min(shortestB,bRun);double start=double.NaN;bool qualifies=false;foreach(var sample in ray){if(Roughness(sample.Cover)=="D"){if(double.IsNaN(start))start=sample.D;double run=sample.D-start;if(double.IsNaN(result.NearestWater)||start<result.NearestWater)result.NearestWater=start;result.LongestWater=Math.Max(result.LongestWater,run);if(start<=result.Transition&&run>=result.DFetch)qualifies=true;}else start=double.NaN;}if(qualifies)smoothRays++;}
 result.Checks.Add(new[]{"Continuous B from site",f(shortestB)+" m (shortest ray)",">= "+f(result.BFetch)+"m required; includes the first sample at/after the boundary"});result.Checks.Add(new[]{"Nearest mapped D start",f(result.NearestWater)+" m","Must be within the D transition distance, or D must start at the site."});result.Checks.Add(new[]{"Longest continuous D run",f(result.LongestWater)+" m",">= "+f(result.DFetch)+"m smooth/unobstructed fetch required"});result.Checks.Add(new[]{"D-qualifying sample rays",smoothRays+" / "+rays.Count,"A mixed sector with a qualifying D ray is screened conservatively as potential D; verify full coverage."});
 if(smoothRays>0){result.Exposure="D";result.Reason="Potential Exposure D: at least one investigation ray has continuous mapped water meeting the smooth-fetch length and site/transition distance. "+(smoothRays<rays.Count?"Mixed coverage: use D as a conservative screening candidate; the map alone does not establish a prevailing full-sector D condition.":"All sampled rays meet this D screening test; verify actual flat/unobstructed conditions.");}
 else if(rays.All(ray=>ray.Where(p=>p.D<=result.BFetch).Concat(ray.Where(p=>p.D>=result.BFetch).Take(1)).All(p=>Roughness(p.Cover)=="B"))){result.Exposure="B";result.Reason="Potential Exposure B: every investigation ray retains mapped trees/built-up cover through the required B fetch. Confirm obstruction height, size, density and full upwind sector coverage; land-cover class alone is not proof.";}
 else{result.Exposure="C";result.Reason="Exposure C screening: continuous B fetch is not established and no D ray meets both smooth-fetch and transition criteria. "+(WindTin.Finite(result.NearestWater)?"Water is mapped, but its qualifying fetch/shoreline proximity is insufficient for D. ":"")+"Confirm actual open-terrain conditions and scattered obstruction heights.";}
 result.Checks.Add(new[]{"Suggested exposure",result.Exposure,result.Reason});return result;
 }
}
}
